}
#cost-inputs {
    margin-bottom: 20px;
}
button {
    padding: 10px 20px;
    background-color: #4CAF50;
    color: white;
    border: none;
    cursor: pointer;
}
#result {
    font-size: 1.2em;
    margin-top: 20px;
}

function calculateCost() {
    const garageName = document.getElementById('garage-name').value;
    const parkingCost = parseFloat(document.getElementById('parking-cost').value);
    if (isNaN(parkingCost) || parkingCost <= 0) {
        alert('Please enter a valid parking cost.');
        return;
    }
    const hours = prompt('Enter the number of hours parked:', '1');
    if (!hours || isNaN(hours) || hours <= 0) {
        alert('Please enter a valid number of hours.');
        return;
    }
    const totalCost = parkingCost * hours;
    document.getElementById('result').innerHTML = `<p>Total cost for ${garageName}: $${totalCost.toFixed(2)}</p>`;
}

